async function nama(id, ambil) {
  const r = await ambil("/u/" + id);
  return r.status === 200
    ? r.data.nama
    : null;
}

const palsu = async () =>
  ({ status: 200, data: { nama: "Ani" } });
assertSama(await nama(1, palsu), "Ani");

function login(req, db) {
  if (!req.email) return { status: 400 };
  const u = db.cari(req.email);
  if (!u || u.pass !== req.pass)
    return { status: 401 };
  return { status: 200 };
}

assertSama(login({}, db).status, 400);

